// FIX58_APP_GPS_DASHBOARD: backward-compatible read-only metadata.
// Server time prevents fresh GPS being inferred from the mobile poll clock.
$gpsSettings=Schema::hasTable('staff_location_settings')
    ? DB::table('staff_location_settings')->where('id',1)->first() : null;
return response()->json([
    'ok'=>true,
    'locations'=>$rows,
    'server_time'=>\Carbon\CarbonImmutable::now('Asia/Kolkata')->toIso8601String(),
    'settings'=>[
        'latitude'=>$gpsSettings?->latitude===null?null:(float)$gpsSettings->latitude,
        'longitude'=>$gpsSettings?->longitude===null?null:(float)$gpsSettings->longitude,
        'reporting_accuracy_m'=>(int)($gpsSettings?->max_accuracy_m??100),
        'radius_m'=>(int)($gpsSettings?->radius_m??100),
    ],
])->header('Cache-Control','private, no-store, max-age=0');
